      state = NOTHING;
    else
      continue;
  }
  tok = netrcbuffer;
  while(tok) {
    while(ISSPACE(*tok))
      tok++;
    /* tok is first non-space letter */
    if(!*tok || (*tok == '#'))
      /* end of line or the rest is a comment */
      break;

    /* leading double-quote means quoted string */
    quoted = (*tok == '"');

    tok_end = tok;
    if(!quoted) {
      while(!ISSPACE(*tok_end))
        tok_end++;
      *tok_end = 0;
    }
  }
}

